const COUPONS = new Map([["WELCOME", 0.1]]);

export function validate(code) {
  return COUPONS.has(code.trim().toUpperCase());
}

archivos.src/cart.js:
import { validate } from "./coupons.js";

export function total(lines, coupon) {
  const gross = lines.reduce((sum, l) => sum + l.price * l.quantity, 0);
  return coupon && validate(coupon) ? Math.round(gross * 0.9 * 100) / 100 : gross;
}

